  "territoryid" integer,
  "billtoaddressid" integer NOT NULL,
  "shiptoaddressid" integer NOT NULL,
  "shipmethodid" integer NOT NULL,
  "creditcardid" integer,
  "creditcardapprovalcode" character varying(15),
  "currencyrateid" integer,
  "subtotal" numeric(19,4) NOT NULL DEFAULT 0.0000,
  "taxamt" numeric(19,4) NOT NULL DEFAULT 0.0000,
  "freight" numeric(19,4) NOT NULL DEFAULT 0.0000,
  "totaldue" numeric(19,4) GENERATED ALWAYS AS (coalesce((("subtotal" + "taxamt") + "freight"),0)) STORED,
  "comment" character varying(128),
  "rowguid" character(36) NOT NULL,
  "modifieddate" timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("salesorderid")
);

CREATE TABLE "sales_specialoffer" (
  "specialofferid" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "description" character varying(255) NOT NULL,
  "discountpct" numeric(10,4) NOT NULL DEFAULT 0.0000,
  "type" character varying(50) NOT NULL,
  "category" character varying(50) NOT NULL,
  "startdate" timestamp(0) without time zone NOT NULL,
  "enddate" timestamp(0) without time zone NOT NULL,
  "minqty" integer NOT NULL DEFAULT 0,
  "maxqty" integer,
  "rowguid" character(36) NOT NULL,
  "modifieddate" timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("specialofferid")
);

CREATE TABLE "sales_specialofferproduct" (
  "specialofferid" integer NOT NULL,
  "productid" integer NOT NULL,
  "rowguid" character(36) NOT NULL,
  "modifieddate" timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("specialofferid", "productid")
);

CREATE TABLE "sales_salesorderdetail" (
  "salesorderid" integer NOT NULL,
  "salesorderdetailid" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "carriertrackingnumber" character varying(25),
  "orderqty" smallint NOT NULL,
  "productid" integer NOT NULL,
  "specialofferid" integer NOT NULL,
  "unitprice" numeric(19,4) NOT NULL,
  "unitpricediscount" numeric(19,4) NOT NULL DEFAULT 0.0000,
  "linetotal" numeric(38,6) GENERATED ALWAYS AS (coalesce((("unitprice" * (1.0 - "unitpricediscount")) * "orderqty"),0.0)) STORED,
  "rowguid" character(36) NOT NULL,
  "modifieddate" timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("salesorderid", "salesorderdetailid")
);

CREATE TABLE "sales_salesreason" (
  "salesreasonid" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" character varying(50) NOT NULL,
  "reasontype" character varying(50) NOT NULL,
  "modifieddate" timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("salesreasonid")
);

CREATE TABLE "sales_salesorderheadersalesreason" (
  "salesorderid" integer NOT NULL,
  "salesreasonid" integer NOT NULL,
  "modifieddate" timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("salesorderid", "salesreasonid")
);

CREATE TABLE "sales_salespersonquotahistory" (
  "businessentityid" integer NOT NULL,
  "quotadate" timestamp(0) without time zone NOT NULL,
  "salesquota" numeric(19,4) NOT NULL,
  "rowguid" character(36) NOT NULL,
  "modifieddate" timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("businessentityid", "quotadate")
);

CREATE TABLE "sales_salestaxrate" (
  "salestaxrateid" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "stateprovinceid" integer NOT NULL,
  "taxtype" smallint NOT NULL,
  "taxrate" numeric(10,4) NOT NULL DEFAULT 0.0000,
  "name" character varying(50) NOT NULL,
  "rowguid" character(36) NOT NULL,
  "modifieddate" timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("salestaxrateid")
);

CREATE TABLE "sales_salesterritoryhistory" (
  "businessentityid" integer NOT NULL,
  "territoryid" integer NOT NULL,
  "startdate" timestamp(0) without time zone NOT NULL,
  "enddate" timestamp(0) without time zone,
  "rowguid" character(36) NOT NULL,
  "modifieddate" timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("businessentityid", "startdate", "territoryid")
);

CREATE TABLE "sales_shoppingcartitem" (
  "shoppingcartitemid" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "shoppingcartid" character varying(50) NOT NULL,
  "quantity" integer NOT NULL DEFAULT 1,
  "productid" integer NOT NULL,
  "datecreated" timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "modifieddate" timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("shoppingcartitemid")
);

